B=ROOT/'study/dataset_20261029';raw=B/'local_export';alias='OH/OH_0p125_interface_Au';folder=raw/alias/'XAS/FDMNES/green';root=read_poscar(raw/alias/'CONTCAR');alllink={l:correspondence(root,deck_structure(folder/f'layer_{l}/Cu_layer{l}_in.txt')) for l in native(folder)};assert all(alllink[l]['status']=='matched' for l in [4,5]);s=deck_structure(folder/'layer_5/Cu_layer5_in.txt');graph=snapshot_graph(s);assert graph['status']=='verified';evid={str(l):layer_evidence(folder/f'layer_{l}',l,s) for l in [4,5]};audit=json.load(open(B/'record_geometry_audit.json'));row=next(x for x in audit if x['configuration']==alias);row.update(eligible=True,exclusion=None,record_scope='top-two ONLY; deeper layers2/3 have incompatible geometry and are excluded explicitly',graph_status=graph['status'],observed_counts=graph['counts'],identity_labels=graph['identities'],group=geometry_hash(s),n_CO=0,coverage_ML=0.,coverage_CO_per_nm2=0.,coverage_per_surface_Cu=0.,CO_only=False,surface_sites=68,surface_Cu=36,surface_Au=32,cell_area_A2=float(np.linalg.norm(np.cross(s['cell'][0],s['cell'][1]))),CONTCAR_available=True,CONTCAR_mapping=alllink[5],layer_evidence=evid,layer_geometry_comparison=alllink)
