m=json.load(open(B/'configuration_manifest.json'));g=json.load(open(B/'geometry_arrays.json'));z=np.load(B/'spectra.npz');arrays=dict(z);assert alias not in {r['configuration'] for r in m};i=len(m);m.append(row);g.append({'configuration':alias,**{k:np.asarray(v).tolist() for k,v in s.items()}});fs=native(folder);assert np.array_equal(fs[4][1][:,0],fs[5][1][:,0]);arrays[f'raw_{i}']=(fs[4][1][:,1]+fs[5][1][:,1])/2;arrays[f'energy_{i}']=fs[4][1][:,0];dump(B/'configuration_manifest.json',m);dump(B/'geometry_arrays.json',g);np.savez_compressed(B/'spectra.npz',**arrays);dump(B/'top_two_recovery.json',{'configuration':alias,'source_root_CONTCAR_sha256':sha(raw/alias/'CONTCAR'),'layer_comparison':alllink,'proof':'Both required layers match actual CONTCAR and full physical populations; deeper layers are excluded, not substituted or relabeled','scope':row['record_scope'],'cohort_finalization':'geometry-based recovery before interpreting training metrics'})
